package com.votehub.util;
import java.nio.charset.StandardCharsets; import java.security.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec;
public class Crypto { public static String sha256(String s){try{var md=MessageDigest.getInstance("SHA-256");return hex(md.digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new RuntimeException(e);}} public static String hmac(String s){try{var m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(System.getenv().getOrDefault("VOTEHUB_SECRET","VoteHubDemoSecretChangeMe").getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return hex(m.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new RuntimeException(e);}} public static String hex(byte[] b){var x=new StringBuilder();for(byte v:b)x.append(String.format("%02x",v));return x.toString();}}
